def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def id_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def cmp(a, b):
        (amaj, amin, apat, apre) = a
        (bmaj, bmin, bpat, bpre) = b
        if amaj != bmaj:
            return -1 if amaj < bmaj else 1
        if amin != bmin:
            return -1 if amin < bmin else 1
        if apat != bpat:
            return -1 if apat < bpat else 1
        if apre is None and bpre is None:
            return 0
        if apre is None:
            return 1
        if bpre is None:
            return -1
        for x, y in zip(apre, bpre):
            kx, ky = id_key(x), id_key(y)
            if kx != ky:
                return -1 if kx < ky else 1
        if len(apre) != len(bpre):
            return -1 if len(apre) < len(bpre) else 1
        return 0

    import functools
    parsed = [(parse(v), v) for v in versions]
    parsed_sorted = sorted(parsed, key=functools.cmp_to_key(lambda a, b: cmp(a[0], b[0])))
    return [v for _, v in parsed_sorted]

